/** Injetada pelo Vite `define` (vite.config.ts) com a versão do package.json.
 *  Declarada AQUI (arquivo .d.ts) pra o typecheck enxergar — o Vite substitui o
 *  identificador por uma string literal apenas nos arquivos que ele processa. */
declare const __APP_VERSION__: string
/** Hash do build (Netlify SOURCE_VERSION = SHA do commit; dev = carimbo). */
declare const __APP_BUILD__: string
